g(){ id=$1; shift; ( /usr/bin/time -p ply generate "$@" --job $id --json > logs/$id.json 2> logs/$id.err; echo "$id exit=$?" ) & }
g w1-wire "A single glowing neon orange light cable, a thin luminous wire that starts at the left edge and curves smoothly in a gentle S-shape to the right edge, bright hot-white core with an orange glow, a few tiny sparks, on a pure black background. Nothing else in the frame." --size 1536x1024
g f1-frame "A thin glowing neon orange rectangular outline frame with rounded corners, empty and hollow inside, bright hot-white core with orange glow, plus three short neon emphasis tick marks radiating from outside its top-right corner, on a pure black background. Nothing else, no text." --size 1536x1024
